"""Central, JSON-backed MultiVision configuration."""

import json
import math
import pathlib
import sys
import tempfile
import threading
from collections.abc import Mapping
from dataclasses import dataclass, field
from types import MappingProxyType
from typing import Any

from multivision.errors import ConfigurationError
from multivision.overlays import OverlayConfiguration
from multivision.pattern import (
    DEFAULT_TAG_DICTIONARY,
    validate_tag_dictionary,
)
from multivision.types import (
    Resolution,
    is_valid_resolution,
)


if sys.platform == 'darwin':
    DEFAULT_CONFIG_PATH = (
        pathlib.Path.home()
        / 'Library'
        / 'Application Support'
        / 'MultiVision'
        / 'config.json'
    )
else:
    DEFAULT_CONFIG_PATH = pathlib.Path.home() / '.config' / 'multivision' / 'config.json'

_CONFIG_FILE_LOCKS: dict[pathlib.Path, threading.RLock] = {}
_CONFIG_FILE_LOCKS_GUARD = threading.Lock()


@dataclass(frozen=True)
class CalibrationThresholds:
    max_mean_reprojection_error: float = 5.0
    max_reprojection_error: float = 10.0
    max_capture_white_balance_delta: float = 0.01
    max_capture_p95_sigma_pixels: float = 5.0
    min_inlier_ratio: float = 0.5
    min_unique_tags: int = 2
    min_spatial_coverage: float = 0.1
    valid_region_margin: float = 0.05

    def __post_init__(self) -> None:
        _validate_thresholds(self)


@dataclass(frozen=True)
class MetricCalibrationThresholds:
    ransac_reprojection_threshold_mm: float = 3.0
    max_capture_white_balance_delta: float = 0.01
    max_capture_corner_jitter_pixels: float = 2.0
    max_mean_fit_error_mm: float = 2.0
    max_fit_error_mm: float = 5.0
    min_inlier_ratio: float = 0.5
    min_unique_target_fiducials: int = 4
    min_capture_marker_ratio: float = 0.8
    min_spatial_coverage: float = 0.5

    def __post_init__(self) -> None:
        _validate_metric_thresholds(self)


@dataclass(frozen=True)
class ProjectorOutputDescriptor:
    projector_resolution: Resolution
    output_identity: str = 'default'

    def __post_init__(self) -> None:
        _validate_resolution(
            self.projector_resolution,
            'projector_output.projector_resolution',
        )
        _validate_output_identity(self.output_identity)


@dataclass(frozen=True)
class FiducialGroup:
    dictionary: str
    marker_size_mm: float

    def __post_init__(self) -> None:
        _validate_tag_dictionary(self.dictionary)
        _validate_finite_positive_number(self.marker_size_mm, 'marker_size_mm')

    @classmethod
    def from_data(
        cls: type['FiducialGroup'],
        data: Mapping[str, Any],
    ) -> 'FiducialGroup':
        if not isinstance(data, Mapping):
            raise ConfigurationError('fiducial group must be an object')
        if set(data) != {'dictionary', 'marker_size_mm'}:
            raise ConfigurationError(
                'fiducial group must contain only dictionary and marker_size_mm',
            )
        try:
            return cls(data['dictionary'], data['marker_size_mm'])
        except KeyError as ex:
            raise ConfigurationError(
                f'fiducial group is missing {ex.args[0]}',
            ) from ex
        except (TypeError, ValueError) as ex:
            raise ConfigurationError(str(ex)) from ex


@dataclass(frozen=True)
class Configuration:
    projector_resolution: Resolution = field(
        default_factory=lambda: Resolution(1920, 1080),
    )
    calibration_thresholds: CalibrationThresholds = field(
        default_factory=CalibrationThresholds,
    )
    calibration_version: int = 1
    projector_output_identity: str = 'default'
    metric_calibration_thresholds: MetricCalibrationThresholds = field(
        default_factory=MetricCalibrationThresholds,
    )
    overlay_limits: OverlayConfiguration = field(default_factory=OverlayConfiguration)
    tag_dictionary: str = DEFAULT_TAG_DICTIONARY
    fiducial_groups: Mapping[str, FiducialGroup] = field(default_factory=dict)
    fiducial_history_length: int = 8
    fiducial_tracking_rate_hz: float = 30.0
    fiducial_grace_period_seconds: float = 5.0
    fiducial_protection_margin_mm: float = 5.0
    max_batch_operations: int = 100
    preview_mode: str = 'active'
    preview_low_rate_hz: float = 10.0

    def __post_init__(self) -> None:
        _validate_resolution(self.projector_resolution, 'projector_resolution')
        _validate_output_identity(self.projector_output_identity)
        if not isinstance(self.calibration_thresholds, CalibrationThresholds):
            raise ConfigurationError('calibration_thresholds must be CalibrationThresholds')
        if not isinstance(
            self.metric_calibration_thresholds,
            MetricCalibrationThresholds,
        ):
            raise ConfigurationError(
                'metric_calibration_thresholds must be MetricCalibrationThresholds',
            )
        if not isinstance(self.overlay_limits, OverlayConfiguration):
            raise ConfigurationError('overlay_limits must be OverlayConfiguration')
        _validate_positive_integer(self.calibration_version, 'calibration_version')
        _validate_tag_dictionary(self.tag_dictionary)
        object.__setattr__(
            self,
            'fiducial_groups',
            _normalise_fiducial_groups(self.fiducial_groups),
        )
        _validate_bounded_positive_integer(
            self.fiducial_history_length,
            'fiducial_history_length',
            32,
        )
        _validate_bounded_number(
            self.fiducial_tracking_rate_hz,
            'fiducial_tracking_rate_hz',
            1.0,
            60.0,
        )
        _validate_bounded_number(
            self.fiducial_grace_period_seconds,
            'fiducial_grace_period_seconds',
            0.1,
            60.0,
        )
        _validate_bounded_number(
            self.fiducial_protection_margin_mm,
            'fiducial_protection_margin_mm',
            0.1,
            1000.0,
        )
        _validate_bounded_positive_integer(
            self.max_batch_operations,
            'max_batch_operations',
            1000,
        )
        _validate_preview_mode(self.preview_mode)
        _validate_bounded_number(
            self.preview_low_rate_hz,
            'preview_low_rate_hz',
            1.0,
            15.0,
        )

    @property
    def projector_output_descriptor(self) -> ProjectorOutputDescriptor:
        return ProjectorOutputDescriptor(
            self.projector_resolution,
            self.projector_output_identity,
        )

    @classmethod
    def from_data(
        cls: type['Configuration'],
        data: Mapping[str, Any],
    ) -> 'Configuration':
        if not isinstance(data, Mapping):
            raise ConfigurationError('The configuration root must be an object')

        projector_resolution = _parse_resolution(data.get('projector_resolution', {}))
        projector_output_identity = data.get('projector_output_identity', 'default')
        thresholds = _parse_thresholds(data.get('calibration_thresholds', {}))
        metric_thresholds = _parse_metric_thresholds(
            data.get('metric_calibration_thresholds', {}),
        )
        overlay_limits = _parse_overlay_configuration(
            data.get('overlay_limits', {}),
        )
        calibration_version = data.get('calibration_version', 1)
        tag_dictionary = data.get('tag_dictionary', DEFAULT_TAG_DICTIONARY)
        fiducial_groups = _parse_fiducial_groups(data.get('fiducial_groups', {}))

        return cls(
            projector_resolution=projector_resolution,
            projector_output_identity=projector_output_identity,
            calibration_thresholds=thresholds,
            metric_calibration_thresholds=metric_thresholds,
            overlay_limits=overlay_limits,
            calibration_version=calibration_version,
            tag_dictionary=tag_dictionary,
            fiducial_groups=fiducial_groups,
            fiducial_history_length=data.get('fiducial_history_length', 8),
            fiducial_tracking_rate_hz=data.get('fiducial_tracking_rate_hz', 30.0),
            fiducial_grace_period_seconds=data.get('fiducial_grace_period_seconds', 5.0),
            fiducial_protection_margin_mm=data.get(
                'fiducial_protection_margin_mm',
                5.0,
            ),
            max_batch_operations=data.get('max_batch_operations', 100),
            preview_mode=data.get('preview_mode', 'active'),
            preview_low_rate_hz=data.get('preview_low_rate_hz', 10.0),
        )

    def to_data(self) -> dict[str, Any]:
        return {
            'projector_resolution': {
                'width': self.projector_resolution.width,
                'height': self.projector_resolution.height,
            },
            'projector_output_identity': self.projector_output_identity,
            'calibration_thresholds': {
                'max_mean_reprojection_error': (
                    self.calibration_thresholds.max_mean_reprojection_error
                ),
                'max_reprojection_error': self.calibration_thresholds.max_reprojection_error,
                'max_capture_white_balance_delta': (
                    self.calibration_thresholds.max_capture_white_balance_delta
                ),
                'max_capture_p95_sigma_pixels': (
                    self.calibration_thresholds.max_capture_p95_sigma_pixels
                ),
                'min_inlier_ratio': self.calibration_thresholds.min_inlier_ratio,
                'min_unique_tags': self.calibration_thresholds.min_unique_tags,
                'min_spatial_coverage': self.calibration_thresholds.min_spatial_coverage,
                'valid_region_margin': self.calibration_thresholds.valid_region_margin,
            },
            'metric_calibration_thresholds': {
                'ransac_reprojection_threshold_mm': (
                    self.metric_calibration_thresholds.ransac_reprojection_threshold_mm
                ),
                'max_capture_white_balance_delta': (
                    self.metric_calibration_thresholds.max_capture_white_balance_delta
                ),
                'max_capture_corner_jitter_pixels': (
                    self.metric_calibration_thresholds.max_capture_corner_jitter_pixels
                ),
                'max_mean_fit_error_mm': self.metric_calibration_thresholds.max_mean_fit_error_mm,
                'max_fit_error_mm': self.metric_calibration_thresholds.max_fit_error_mm,
                'min_inlier_ratio': self.metric_calibration_thresholds.min_inlier_ratio,
                'min_unique_target_fiducials': (
                    self.metric_calibration_thresholds.min_unique_target_fiducials
                ),
                'min_capture_marker_ratio': (
                    self.metric_calibration_thresholds.min_capture_marker_ratio
                ),
                'min_spatial_coverage': self.metric_calibration_thresholds.min_spatial_coverage,
            },
            'overlay_limits': self.overlay_limits.to_data(),
            'calibration_version': self.calibration_version,
            'tag_dictionary': self.tag_dictionary,
            'fiducial_groups': {
                group_name: {
                    'dictionary': group.dictionary,
                    'marker_size_mm': group.marker_size_mm,
                }
                for group_name, group in self.fiducial_groups.items()
            },
            'fiducial_history_length': self.fiducial_history_length,
            'fiducial_tracking_rate_hz': self.fiducial_tracking_rate_hz,
            'fiducial_grace_period_seconds': self.fiducial_grace_period_seconds,
            'fiducial_protection_margin_mm': self.fiducial_protection_margin_mm,
            'max_batch_operations': self.max_batch_operations,
            'preview_mode': self.preview_mode,
            'preview_low_rate_hz': self.preview_low_rate_hz,
        }


def load_configuration(config_path: pathlib.Path | None = None) -> Configuration:
    """Load the one MultiVision configuration file, using defaults if absent."""
    config_path = _resolve_config_path(config_path)
    try:
        raw_configuration = config_path.read_text(encoding='utf-8')
    except FileNotFoundError:
        return Configuration()
    except (OSError, UnicodeDecodeError) as ex:
        raise ConfigurationError(f'Could not read configuration at {config_path}') from ex

    try:
        data = json.loads(raw_configuration)
    except json.JSONDecodeError as ex:
        raise ConfigurationError(f'Could not read configuration at {config_path}') from ex

    return Configuration.from_data(data)


def save_configuration(
    configuration: Configuration,
    config_path: pathlib.Path | None = None,
) -> None:
    """Save the central configuration as readable JSON."""
    if not isinstance(configuration, Configuration):
        raise ConfigurationError('configuration must be a Configuration')
    config_path = _resolve_config_path(config_path)
    temporary_path: pathlib.Path | None = None
    with _get_configuration_file_lock(config_path):
        try:
            config_path.parent.mkdir(parents=True, exist_ok=True)
            data = _load_existing_document_for_update(config_path)
            data.update(configuration.to_data())
            serialised_configuration = json.dumps(
                data,
                indent=2,
                sort_keys=True,
                allow_nan=False,
            ) + '\n'
            with tempfile.NamedTemporaryFile(
                mode='w',
                encoding='utf-8',
                dir=config_path.parent,
                prefix=f'.{config_path.name}.',
                delete=False,
            ) as temporary_file:
                temporary_path = pathlib.Path(temporary_file.name)
                temporary_file.write(serialised_configuration)
            temporary_path.replace(config_path)
        except (OSError, TypeError, ValueError) as ex:
            raise ConfigurationError(f'Could not write configuration at {config_path}') from ex
        finally:
            if temporary_path is not None and temporary_path.exists():
                try:
                    temporary_path.unlink()
                except OSError:
                    pass


def _get_configuration_file_lock(config_path: pathlib.Path) -> threading.RLock:
    lock_path = config_path.resolve()
    with _CONFIG_FILE_LOCKS_GUARD:
        lock = _CONFIG_FILE_LOCKS.get(lock_path)
        if lock is None:
            lock = threading.RLock()
            _CONFIG_FILE_LOCKS[lock_path] = lock
        return lock


def _resolve_config_path(config_path: pathlib.Path | None) -> pathlib.Path:
    if config_path is None:
        return DEFAULT_CONFIG_PATH
    if not isinstance(config_path, pathlib.Path):
        raise ConfigurationError('config_path must be a pathlib.Path')
    return config_path


def _parse_resolution(data: Any) -> Resolution:
    if not isinstance(data, Mapping):
        raise ConfigurationError('projector_resolution must be an object')

    width = data.get('width', 1920)
    height = data.get('height', 1080)
    _validate_positive_integer(width, 'projector_resolution.width')
    _validate_positive_integer(height, 'projector_resolution.height')
    return Resolution(width, height)


def _parse_metric_thresholds(data: Any) -> MetricCalibrationThresholds:
    if not isinstance(data, Mapping):
        raise ConfigurationError('metric_calibration_thresholds must be an object')

    defaults = MetricCalibrationThresholds()
    values = {
        'ransac_reprojection_threshold_mm': data.get(
            'ransac_reprojection_threshold_mm',
            defaults.ransac_reprojection_threshold_mm,
        ),
        'max_capture_white_balance_delta': data.get(
            'max_capture_white_balance_delta',
            defaults.max_capture_white_balance_delta,
        ),
        'max_capture_corner_jitter_pixels': data.get(
            'max_capture_corner_jitter_pixels',
            defaults.max_capture_corner_jitter_pixels,
        ),
        'max_mean_fit_error_mm': data.get(
            'max_mean_fit_error_mm',
            defaults.max_mean_fit_error_mm,
        ),
        'max_fit_error_mm': data.get(
            'max_fit_error_mm',
            defaults.max_fit_error_mm,
        ),
        'min_inlier_ratio': data.get('min_inlier_ratio', defaults.min_inlier_ratio),
        'min_unique_target_fiducials': data.get(
            'min_unique_target_fiducials',
            defaults.min_unique_target_fiducials,
        ),
        'min_capture_marker_ratio': data.get(
            'min_capture_marker_ratio',
            defaults.min_capture_marker_ratio,
        ),
        'min_spatial_coverage': data.get(
            'min_spatial_coverage',
            defaults.min_spatial_coverage,
        ),
    }
    return MetricCalibrationThresholds(**values)


def _parse_fiducial_groups(data: Any) -> dict[str, FiducialGroup]:
    if not isinstance(data, Mapping):
        raise ConfigurationError('fiducial_groups must be an object')

    groups: dict[str, FiducialGroup] = {}
    for group_name, group_data in data.items():
        _validate_group_name(group_name)
        groups[group_name] = FiducialGroup.from_data(group_data)
    return groups


def _normalise_fiducial_groups(
    groups: Mapping[str, FiducialGroup],
) -> Mapping[str, FiducialGroup]:
    if not isinstance(groups, Mapping):
        raise ConfigurationError('fiducial_groups must be an object')

    normalised: dict[str, FiducialGroup] = {}
    for group_name, group in groups.items():
        _validate_group_name(group_name)
        if isinstance(group, FiducialGroup):
            normalised[group_name] = group
            continue
        if isinstance(group, Mapping):
            normalised[group_name] = FiducialGroup.from_data(group)
            continue
        raise ConfigurationError(
            f'fiducial_groups[{group_name!r}] must be a FiducialGroup',
        )
    return MappingProxyType(normalised)


def _parse_overlay_configuration(data: Any) -> OverlayConfiguration:
    try:
        return OverlayConfiguration.from_data(data)
    except (TypeError, ValueError) as ex:
        raise ConfigurationError(str(ex)) from ex


def _parse_thresholds(data: Any) -> CalibrationThresholds:
    if not isinstance(data, Mapping):
        raise ConfigurationError('calibration_thresholds must be an object')

    defaults = CalibrationThresholds()
    values = {
        'max_mean_reprojection_error': data.get(
            'max_mean_reprojection_error',
            defaults.max_mean_reprojection_error,
        ),
        'max_reprojection_error': data.get(
            'max_reprojection_error',
            defaults.max_reprojection_error,
        ),
        'max_capture_white_balance_delta': data.get(
            'max_capture_white_balance_delta',
            defaults.max_capture_white_balance_delta,
        ),
        'max_capture_p95_sigma_pixels': data.get(
            'max_capture_p95_sigma_pixels',
            defaults.max_capture_p95_sigma_pixels,
        ),
        'min_inlier_ratio': data.get('min_inlier_ratio', defaults.min_inlier_ratio),
        'min_unique_tags': data.get('min_unique_tags', defaults.min_unique_tags),
        'min_spatial_coverage': data.get(
            'min_spatial_coverage',
            defaults.min_spatial_coverage,
        ),
        'valid_region_margin': data.get(
            'valid_region_margin',
            defaults.valid_region_margin,
        ),
    }

    return CalibrationThresholds(**values)


def _load_existing_document_for_update(config_path: pathlib.Path) -> dict[str, Any]:
    try:
        raw_data = config_path.read_text(encoding='utf-8')
    except FileNotFoundError:
        return {}
    except (OSError, UnicodeDecodeError) as ex:
        raise ConfigurationError(f'Could not read configuration at {config_path}') from ex
    try:
        data = json.loads(raw_data)
    except json.JSONDecodeError as ex:
        raise ConfigurationError(f'Could not read configuration at {config_path}') from ex
    if not isinstance(data, dict):
        raise ConfigurationError(f'Configuration at {config_path} must be an object')
    return data


def _validate_resolution(value: Any, field_name: str) -> None:
    if not is_valid_resolution(value):
        raise ConfigurationError(f'{field_name} must be a positive Resolution')


def _validate_thresholds(value: Any) -> None:
    _validate_finite_non_negative_numbers(
        value,
        (
            'max_mean_reprojection_error',
            'max_reprojection_error',
            'max_capture_white_balance_delta',
            'max_capture_p95_sigma_pixels',
            'min_inlier_ratio',
            'min_spatial_coverage',
            'valid_region_margin',
        ),
    )

    _validate_positive_integer(value.min_unique_tags, 'min_unique_tags')
    if value.max_capture_p95_sigma_pixels <= 0:
        raise ConfigurationError('max_capture_p95_sigma_pixels must be positive')
    if (
        value.max_capture_white_balance_delta <= 0
        or value.max_capture_white_balance_delta > 1
    ):
        raise ConfigurationError(
            'max_capture_white_balance_delta must be between 0 and 1',
        )
    if value.min_inlier_ratio > 1 or value.min_spatial_coverage > 1:
        raise ConfigurationError('ratio and coverage thresholds must be between 0 and 1')
    if value.valid_region_margin > 1:
        raise ConfigurationError('valid_region_margin must be between 0 and 1')


def _validate_metric_thresholds(value: MetricCalibrationThresholds) -> None:
    _validate_finite_non_negative_numbers(
        value,
        (
            'ransac_reprojection_threshold_mm',
            'max_capture_white_balance_delta',
            'max_capture_corner_jitter_pixels',
            'max_mean_fit_error_mm',
            'max_fit_error_mm',
            'min_inlier_ratio',
            'min_capture_marker_ratio',
            'min_spatial_coverage',
        ),
    )

    if value.ransac_reprojection_threshold_mm <= 0:
        raise ConfigurationError(
            'ransac_reprojection_threshold_mm must be positive',
        )
    if value.max_capture_white_balance_delta <= 0 or value.max_capture_white_balance_delta > 1:
        raise ConfigurationError(
            'max_capture_white_balance_delta must be between 0 and 1',
        )
    if value.max_capture_corner_jitter_pixels <= 0:
        raise ConfigurationError(
            'max_capture_corner_jitter_pixels must be positive',
        )
    _validate_positive_integer(
        value.min_unique_target_fiducials,
        'min_unique_target_fiducials',
    )
    if value.min_capture_marker_ratio <= 0:
        raise ConfigurationError('min_capture_marker_ratio must be positive')
    if (
        value.min_inlier_ratio > 1
        or value.min_capture_marker_ratio > 1
        or value.min_spatial_coverage > 1
    ):
        raise ConfigurationError('ratio and coverage thresholds must be between 0 and 1')


def _validate_finite_non_negative_numbers(
    value: Any,
    field_names: tuple[str, ...],
) -> None:
    for field_name in field_names:
        field_value = getattr(value, field_name)
        if not isinstance(field_value, (int, float)) or isinstance(field_value, bool):
            raise ConfigurationError(f'{field_name} must be a number')
        try:
            is_finite = math.isfinite(field_value)
        except (OverflowError, TypeError, ValueError):
            is_finite = False
        if not is_finite:
            raise ConfigurationError(f'{field_name} must be finite')
        if field_value < 0:
            raise ConfigurationError(f'{field_name} must not be negative')


def _validate_group_name(value: Any) -> None:
    if not isinstance(value, str) or len(value.strip()) == 0:
        raise ConfigurationError('fiducial group names must be non-empty strings')


def _validate_bounded_positive_integer(value: Any, field_name: str, maximum: int) -> None:
    _validate_positive_integer(value, field_name)
    if value > maximum:
        raise ConfigurationError(f'{field_name} must not exceed {maximum}')


def _validate_bounded_number(
    value: Any,
    field_name: str,
    minimum: float,
    maximum: float,
) -> None:
    try:
        is_finite = math.isfinite(value)
    except (OverflowError, TypeError, ValueError):
        is_finite = False
    if (
        not isinstance(value, (int, float))
        or isinstance(value, bool)
        or not is_finite
        or value < minimum
        or value > maximum
    ):
        raise ConfigurationError(
            f'{field_name} must be finite and between {minimum} and {maximum}',
        )


def _validate_finite_positive_number(value: Any, field_name: str) -> None:
    try:
        is_finite = math.isfinite(value)
    except (OverflowError, TypeError, ValueError):
        is_finite = False
    if (
        not isinstance(value, (int, float))
        or isinstance(value, bool)
        or not is_finite
        or value <= 0
    ):
        raise ConfigurationError(f'{field_name} must be a finite positive number')


def _validate_preview_mode(value: Any) -> None:
    if not isinstance(value, str) or value not in {'active', 'low_rate', 'off'}:
        raise ConfigurationError('preview_mode must be active, low_rate or off')


def _validate_tag_dictionary(value: Any) -> None:
    try:
        validate_tag_dictionary(value)
    except ValueError as ex:
        raise ConfigurationError(str(ex)) from ex


def _validate_output_identity(value: Any) -> None:
    if not isinstance(value, str) or len(value) == 0:
        raise ConfigurationError('projector_output_identity must be a non-empty string')


def _validate_positive_integer(value: Any, field_name: str) -> None:
    if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
        raise ConfigurationError(f'{field_name} must be a positive integer')

# Plan6 validation contract: configurable planar tag observations

## Intent and scope

Plan6 adds one read-only capability for inspecting fiducial tags in one camera's latest retained frame:

```text
multivision tags list --camera <camera> [--dictionary <dictionary>]
```

The capability returns every valid tag detection, including detections whose IDs are unknown to the calibration pattern and multiple detections carrying the same marker ID, with camera-native planar image geometry and, when available, the corresponding projector-native planar geometry. It does not persist observations, identify cards, infer stacks, track tags across frames, or mutate overlays.

The query uses the existing persistent camera runtime and latest-frame ownership. The CLI and HTTP API never open or read camera handles directly.

## Accepted geometry meaning

Plan6 reports 2D planar observations in two coordinate spaces:

- centre position;
- ordered four-corner polygon;
- apparent polygon area;
- orientation of the ordered corner-0→corner-1 edge in that coordinate space.

Camera-space `orientation_degrees` is an apparent image-plane angle only. Perspective can make it differ from the tag's physical yaw on the table, so callers must not interpret camera-space orientation as physical table yaw.

Projector-space `orientation_degrees` is calculated only after the observed corners are transformed through the current camera→projector homography. Because that homography rectifies the calibrated table plane into projector coordinates, projector-space orientation is the Plan6 representation of planar table orientation for evidence that actually lies on that calibrated plane. It is still not a 3D pose estimate and is invalid for objects displaced materially above or below the calibration plane.

Neither observation means camera-relative 3D translation, height, tilt, roll, pitch, lens pose or physical dimensions. The projector-space orientation represents a card's yaw only when the tag is printed with a known fixed rotation relative to the card. Plan6 does not store card-specific mounting offsets; callers may apply that known offset themselves.

## Dictionary contract

Calibration-pattern detection remains independently configured around the existing `DICT_APRILTAG_36h11` family and must not be changed by this feature.

Generic tag inspection has a separate `tag_dictionary` configuration field whose default is:

```text
DICT_5X5_1000
```

The request may override that value with `--dictionary` or the equivalent HTTP query parameter. The initial supported set includes `DICT_5X5_1000` and the currently supported AprilTag-family names. Configuration/request validation rejects names outside that canonical set; OpenCV availability is checked when the detector is constructed at request time, and an unavailable supported constant is an explicit detection error. A typo must not silently select another dictionary.

One request uses one dictionary. Multi-family scanning is out of scope.

## Detection and frame contract

The service resolves one camera reference using the existing session identity rules, requires the camera to be open, available and to have a usable latest frame, then runs the configured detector on that frame.

The response includes:

- requested camera reference as `camera`;
- resolved session slot/stable identity as `camera_id` where available;
- dictionary name;
- frame counter;
- capture timestamp;
- every valid tag detection, with duplicate marker IDs retained as independent observations;
- deterministic ordering by `(marker_id, centre_y, centre_x)`, using the validated camera-space diagonal-intersection centre as the tie-breaker for duplicate IDs.

No temporal averaging, tracking, debounce or latest-frame retry is introduced. An empty valid frame produces an empty `tags` list. Detector failures remain explicit errors.

The existing calibration detector seam remains available for calibration, but generic inspection has a separate dictionary-aware detector factory/cache (plus an injectable factory for tests). Calibration explicitly constructs or selects a detector for `calibration_pattern.marker_family`; a card-tag dictionary must never replace that detector. Generic inspection must not pass detections through calibration-pattern correspondence assembly, must not reject unknown IDs, and must not deduplicate repeated IDs because independent tags may legitimately share one ID.

## Planar observation schema

Each tag contains:

```json
{
  "id": 23,
  "camera": {
    "corners": [[x, y], [x, y], [x, y], [x, y]],
    "centre": [x, y],
    "orientation_degrees": 12.5,
    "area_px": 1234.5
  },
  "projector": {
    "corners": [[x, y], [x, y], [x, y], [x, y]],
    "centre": [x, y],
    "orientation_degrees": 11.8,
    "area_px": 987.0
  },
  "projection_status": null
}
```

`camera.orientation_degrees` is explicitly the apparent camera-image orientation. `projector.orientation_degrees` is independently recomputed from transformed corners and is the rectified planar orientation in projector coordinates for evidence lying on the calibrated plane. The two values are not required to match.

The containing response also has `projection_status` for camera-wide failures, while a tag-level status explains an individual unsupported marker geometry.

When the camera-wide calibration is unusable, the top-level status contains the applicable code and every detected tag has `projector: null` with the same status. With usable calibration, the top-level status is `null`; an individual tag has a `null` tag status only when all four corners and its centre project successfully. An individual failure uses the first applicable code in this order: `POINT_OUTSIDE_CALIBRATED_REGION`, `INVALID_HOMOGRAPHY`, then `POINT_OUTSIDE_PROJECTOR_BOUNDS`. An empty tag list has no tag-level statuses, but still reports the camera-wide status.

`projector` is `null` when the current camera/projector calibration is unavailable, stale, invalid, outside its supported calibrated region, or produces an out-of-bounds/non-finite result. `projection_status` is either `null` or an object of the form `{"code": "CALIBRATION_STALE", "message": "..."}` carrying the structured error needed to explain that absence. Raw camera geometry remains available unless camera capture, detection, or validation of that individual detection itself fails.

The response also contains a top-level `projection_status` (`null` or a `{code, message}` object) for camera-wide projection availability. The service/API always expose usable camera geometry and attempt projector geometry. There is no second output-space authority and no need for a separate `--space` mode in this milestone.

## Geometry definitions

- Coordinates are native pixels: camera coordinates use the captured camera resolution; projector coordinates use the active projector output resolution.
- Corners retain the detector's ordered convention and are emitted in that order.
- A usable tag observation requires exactly four finite, non-degenerate corners forming geometry from which the required centre, area and ordered edge can be computed. Existing permissive detector normalisation may omit malformed individual entries; no geometry is fabricated.
- `centre` is the projectively correct centre of the quadrilateral, defined by the intersection of its diagonals; it is not an arbitrary bounding-box centre.
- `area_px` is the absolute polygon area in the relevant pixel space.
- `camera.orientation_degrees` is the angle of the ordered camera-image edge from corner 0 to corner 1, measured with +X right and +Y down, normalised to `[-180, 180)` degrees. It is an apparent image-plane orientation, not physical yaw.
- `projector.orientation_degrees` is the angle of the transformed ordered edge from corner 0 to corner 1 in projector coordinates, using the same axis/sign/normalisation convention. It is calculated after transforming the ordered corners, never copied or adjusted from the camera angle.
- Projector centre is obtained by transforming the validated camera-space diagonal-intersection centre through the existing camera→projector homography.

All reported values must be finite. Individual malformed detector entries are omitted by the existing permissive detector normalisation or by pure observation-geometry validation and are never fabricated into an observation; structural detector failures, mismatched evidence and detector execution failures remain explicit request errors. Duplicate valid IDs are not malformed evidence.

## Projection authority and failure semantics

The current session camera calibration, projector descriptor, camera resolution, persisted `valid_region` and projector bounds remain authoritative. Plan6 makes that persisted calibrated region the single support-region interpretation for both the new tag projection and the legacy point-projection path; it must not leave the legacy path using full camera bounds while tags use a different rule. A non-mutating multi-point helper may be added to the existing point-projection authority so point requests and tag-corner projection share validation and transform logic.

This is an intentional compatibility change to the legacy point-projection contract, not an incidental refactor: a camera-native point may be inside the captured frame bounds yet unsupported because it lies outside the persisted calibrated `valid_region`. Such a request must fail with `POINT_OUTSIDE_CALIBRATED_REGION`. Existing points inside the calibrated region retain their prior successful projection semantics. Tests must exercise both sides of this boundary explicitly.

Projection/status reads must be side-effect free: inspecting tags must not invalidate, replace or clear overlays, calibration records or persistent state. Lifecycle and calibration transitions remain responsible for their existing invalidation outside the query.

Plan6 must not introduce another homography, local scale, DPI estimate, camera intrinsic model or card-height correction.

For a calibrated camera, all four corners and the centre must project successfully before a tag receives a projector observation. If any required point is unsupported, the tag receives no projector geometry and an explicit per-tag projection status. Projection is atomic per tag: partial transformed geometry must not be returned. A camera-wide calibration failure is represented consistently for every detected tag.

Changing camera/projector lifecycle or calibration state must affect only the current query result; tag observations are not persisted and do not become overlays.

## HTTP and CLI contract

Primary HTTP route:

```text
GET /cameras/{camera}/tags?dictionary=DICT_5X5_1000
```

`dictionary` is optional and defaults to the validated configuration value. The route returns the JSON-safe observation document above, including repeated `id` values when duplicate IDs are detected, and preserves existing camera/snapshot/error routes.

Primary CLI route:

```text
multivision tags list --camera overhead
multivision tags list --camera overhead --dictionary DICT_5X5_1000
```

The CLI only validates arguments, encodes the camera/dictionary request, sends HTTP, prints the service response or structured failure, and returns a non-zero status for transport, validation or service failures. It performs no OpenCV, homography, pose or camera work locally.

## Deterministic validation matrix

Tests must cover:

- dictionary configuration round-trip and invalid dictionary rejection;
- `DICT_5X5_1000` detector initialisation and request selection without changing calibration-pattern defaults;
- empty, single and multiple detections with deterministic ordering;
- duplicate IDs retained independently and deterministically tie-broken by camera-space centre;
- unknown IDs retained;
- malformed individual entries being omitted while structural evidence and detector failures remain explicit;
- detector construction being separate for calibration and card-tag inspection, including dictionary-aware injectable factories;
- diagonal-intersection centres, polygon areas and the stated orientation convention;
- camera-image orientation being demonstrably distinct from projector-plane orientation under a perspective homography;
- projector orientation being recomputed from transformed corners rather than copied from camera orientation;
- projective transforms changing both position and orientation correctly;
- non-finite, degenerate, horizon-crossing, calibrated-region and projector-bound failures;
- atomic per-tag projection failure with no partial projector geometry;
- raw results remaining available without usable calibration;
- the intentional legacy point-projection change: a point inside camera bounds but outside `valid_region` fails with `POINT_OUTSIDE_CALIBRATED_REGION`, while supported in-region points continue to project;
- persistent latest-frame use without camera reopen/read ownership leaks;
- session camera references, renamed slots and stale lifecycle/calibration state;
- API schema/query validation, repeated IDs and JSON-safe output;
- CLI delegation, URL encoding, structured failures and no camera/display imports;
- no overlay, calibration-record or persistent-state mutation caused by tag inspection.

Synthetic tests prove deterministic behaviour only. Hardware smoke instructions must remain separate and must not claim physical card/stack accuracy without execution on the target setup. Hardware verification must include several tag rotations and positions and must explicitly treat camera-space orientation as apparent image geometry rather than physical table yaw. Tags materially above the calibration plane are a known limitation of projector-plane correspondence.

## Explicit non-goals

- card identity or card metadata;
- uniqueness of marker IDs across physical tags;
- stack detection or stack-height estimation;
- tag tracking or temporal smoothing;
- multi-camera fusion;
- multi-dictionary scanning in one request;
- true 3D pose or camera intrinsic calibration;
- physical yaw estimation directly from unrectified camera-image orientation;
- card mounting-offset databases;
- projector overlays or rendering changes;
- persistence of tag observations (the configured default dictionary is persisted as ordinary configuration);
- edits to ADR-0001, ADR-0002, ADR-0003 or `harness.toml`.

class MultiVisionError(Exception):
    """Base class for expected MultiVision failures."""


class ConfigurationError(MultiVisionError):
    """Raised when the central configuration cannot be read or validated."""


class GeometryError(MultiVisionError, ValueError):
    """Base class for invalid coordinate and homography operations."""


class PointOutsidePreviewError(GeometryError):
    """Raised when a preview point falls in letterbox padding."""

    code = 'POINT_OUTSIDE_PREVIEW'


class PointOutsideCalibratedRegionError(GeometryError):
    """Raised when a camera point is outside calibrated spatial support."""

    code = 'POINT_OUTSIDE_CALIBRATED_REGION'


class PointOutsideProjectorError(GeometryError):
    """Raised when a projected point falls outside the projector output."""

    code = 'POINT_OUTSIDE_PROJECTOR_BOUNDS'


class InvalidCalibrationStateError(GeometryError):
    """Raised when spatial geometry is requested before verification."""

    code = 'CALIBRATION_INVALID'


class InvalidHomographyError(GeometryError):
    """Raised when a homography cannot safely project points."""

    code = 'INVALID_HOMOGRAPHY'


class InvalidAvailableAreaError(GeometryError):
    """Raised when a camera calibration cannot produce a usable area."""

    code = 'AVAILABLE_AREA_INVALID'


class FiducialDetectionError(MultiVisionError):
    """Raised when the fiducial detector cannot be initialised or run."""


class FiducialGroupDetectionError(FiducialDetectionError):
    """Raised when one configured fiducial group's detector is unavailable."""

    code = 'FIDUCIAL_GROUP_DETECTION_FAILED'

    def __init__(self, group: str, message: str) -> None:
        self.group = group
        super().__init__(f'Fiducial group {group!r}: {message}')


class CalibrationError(MultiVisionError, ValueError):
    """Raised when correspondences cannot produce a trustworthy calibration."""


class HardwareError(MultiVisionError):
    """Base class for failures at a hardware boundary."""


class CameraOpenError(HardwareError):
    """Raised when a camera cannot be opened."""


class CameraUnavailableError(HardwareError):
    """Raised when a configured camera is not available."""

    code = 'CAMERA_UNAVAILABLE'


class OverlayNotFoundError(MultiVisionError, KeyError):
    """Raised when a generic overlay selector is not present in the session."""

    code = 'OVERLAY_NOT_FOUND'


class SessionCameraError(MultiVisionError, ValueError):
    """Base class for invalid in-memory session camera operations."""


class CameraSlotNotFoundError(SessionCameraError):
    """Raised when a session camera slot does not exist."""

    code = 'CAMERA_SLOT_NOT_FOUND'


class DuplicateCameraNameError(SessionCameraError):
    """Raised when a display name is already assigned to another slot."""

    code = 'DUPLICATE_CAMERA_NAME'


class CameraStateError(SessionCameraError):
    """Raised when a session camera lifecycle transition is invalid."""

    code = 'CAMERA_STATE_ERROR'


class ActiveCameraLimitError(CameraStateError):
    """Raised when opening a camera would exceed the active-camera limit."""

    code = 'ACTIVE_CAMERA_LIMIT'


class FrameCaptureError(HardwareError):
    """Raised when an open camera cannot provide a usable frame."""

"""Deterministic projector-space calibration-pattern metadata."""

from __future__ import annotations

import math
from collections.abc import (
    Mapping,
    Sequence,
    Set,
)
from numbers import Real
from typing import NamedTuple

from multivision.geometry import CoordinateBounds, Point2D
from multivision.types import (
    Resolution,
    is_valid_resolution,
)


APRILTAG_36H11 = 'DICT_APRILTAG_36h11'
APRILTAG_FAMILIES = frozenset(
    {
        'DICT_APRILTAG_16h5',
        'DICT_APRILTAG_25h9',
        'DICT_APRILTAG_36h10',
        APRILTAG_36H11,
    },
)
DICT_5X5_1000 = 'DICT_5X5_1000'
SUPPORTED_TAG_DICTIONARIES = APRILTAG_FAMILIES | {DICT_5X5_1000}
DEFAULT_TAG_DICTIONARY = DICT_5X5_1000
DEFAULT_MARKER_COUNT = 20
SUPPORTED_MARKER_COUNTS = frozenset({9, 10, 11, 12, 20})
_DEFAULT_MARKER_SIZE_FRACTION = 0.225


class MarkerCorner(NamedTuple):
    """One ordered, projector-native corner of a calibration marker."""

    marker_id: int
    corner_index: int
    projector_position: Point2D


class CalibrationMarker(NamedTuple):
    """Renderer-facing metadata for one uniquely identified marker."""

    marker_id: int
    corners: tuple[Point2D, ...]

    @property
    def corner_metadata(self) -> tuple[MarkerCorner, ...]:
        return tuple(
            MarkerCorner(self.marker_id, corner_index, projector_position)
            for corner_index, projector_position in enumerate(self.corners)
        )

    @property
    def bounds(self) -> CoordinateBounds:
        x_positions = [corner.x for corner in self.corners]
        y_positions = [corner.y for corner in self.corners]
        return CoordinateBounds(
            min(x_positions),
            min(y_positions),
            max(x_positions),
            max(y_positions),
        )


class CalibrationPattern(NamedTuple):
    """Immutable pattern geometry in projector-native coordinates."""

    projector_resolution: Resolution
    usable_area: CoordinateBounds
    marker_family: str
    marker_size: float
    markers: tuple[CalibrationMarker, ...]

    @property
    def marker_corners(self) -> tuple[MarkerCorner, ...]:
        return tuple(
            corner
            for marker in self.markers
            for corner in marker.corner_metadata
        )

    def get_marker(self, marker_id: int) -> CalibrationMarker:
        """Return the marker with the requested dictionary ID."""
        for marker in self.markers:
            if marker.marker_id == marker_id:
                return marker
        raise KeyError(marker_id)


def validate_tag_dictionary(dictionary_name: object) -> str:
    """Validate one supported OpenCV dictionary name."""
    if (
        not isinstance(dictionary_name, str)
        or dictionary_name not in SUPPORTED_TAG_DICTIONARIES
    ):
        raise ValueError(f'Unsupported tag dictionary: {dictionary_name!r}')
    return dictionary_name


def build_calibration_pattern(
    projector_resolution: Resolution | Sequence[int],
    usable_area: CoordinateBounds | None = None,
    marker_count: int = DEFAULT_MARKER_COUNT,
    marker_size: float | None = None,
    marker_family: str = APRILTAG_36H11,
) -> CalibrationPattern:
    """Build a deterministic grid of uniquely identified AprilTag markers."""
    checked_resolution = _coerce_resolution(projector_resolution)
    checked_area = _coerce_usable_area(
        usable_area
        if usable_area is not None
        else CoordinateBounds(
            0.0,
            0.0,
            float(checked_resolution.width),
            float(checked_resolution.height),
        ),
        checked_resolution,
    )
    _validate_marker_count(marker_count)
    if not isinstance(marker_family, str) or marker_family not in APRILTAG_FAMILIES:
        raise ValueError(f'Unsupported AprilTag family: {marker_family!r}')

    checked_marker_size = marker_size
    if checked_marker_size is None:
        checked_marker_size = _default_marker_size(
            checked_area,
            marker_count,
        )
    checked_marker_size = _coerce_marker_size(
        checked_marker_size,
        checked_area,
        marker_count,
    )

    columns, rows, omitted_slots = _layout_for_marker_count(marker_count)
    x_starts = _build_raster_safe_axis_starts(
        checked_area.left,
        checked_area.right,
        columns,
        checked_marker_size,
    )
    y_starts = _build_raster_safe_axis_starts(
        checked_area.top,
        checked_area.bottom,
        rows,
        checked_marker_size,
    )
    marker_positions = [
        (x_idx, y_idx)
        for y_idx in range(rows)
        for x_idx in range(columns)
        if (x_idx, y_idx) not in omitted_slots
    ]

    markers = tuple(
        CalibrationMarker(
            marker_id,
            _build_marker_corners(
                checked_area,
                x_starts[x_idx],
                y_starts[y_idx],
                checked_marker_size,
            ),
        )
        for marker_id, (x_idx, y_idx) in enumerate(marker_positions)
    )
    return CalibrationPattern(
        checked_resolution,
        checked_area,
        marker_family,
        float(checked_marker_size),
        markers,
    )


def _coerce_resolution(
    resolution: Resolution | Sequence[int],
) -> Resolution:
    if isinstance(resolution, Resolution):
        checked_resolution = resolution
    else:
        if isinstance(resolution, (Mapping, Set, str, bytes, bytearray)):
            raise ValueError('projector_resolution must contain width and height')
        try:
            width, height = resolution
        except (TypeError, ValueError):
            raise ValueError('projector_resolution must contain width and height') from None
        checked_resolution = Resolution(width, height)
    if not is_valid_resolution(checked_resolution):
        raise ValueError('projector_resolution must contain positive integer dimensions')
    try:
        width_as_float = float(checked_resolution.width)
        height_as_float = float(checked_resolution.height)
    except OverflowError:
        raise ValueError('projector_resolution dimensions are too large') from None
    if not math.isfinite(width_as_float) or not math.isfinite(height_as_float):
        raise ValueError('projector_resolution dimensions are too large')
    return checked_resolution


def _coerce_usable_area(
    usable_area: CoordinateBounds,
    projector_resolution: Resolution,
) -> CoordinateBounds:
    if not isinstance(usable_area, CoordinateBounds):
        raise ValueError('usable_area must be CoordinateBounds')
    try:
        checked_area = CoordinateBounds(
            _coerce_finite_float(usable_area.left, 'usable_area'),
            _coerce_finite_float(usable_area.top, 'usable_area'),
            _coerce_finite_float(usable_area.right, 'usable_area'),
            _coerce_finite_float(usable_area.bottom, 'usable_area'),
        )
    except ValueError:
        raise ValueError('usable_area must contain finite coordinates') from None
    if not checked_area.left < checked_area.right or not checked_area.top < checked_area.bottom:
        raise ValueError('usable_area must have positive dimensions')
    if (
        checked_area.left < 0
        or checked_area.top < 0
        or checked_area.right > projector_resolution.width
        or checked_area.bottom > projector_resolution.height
    ):
        raise ValueError('usable_area must be inside projector_resolution')
    return checked_area


def _validate_marker_count(marker_count: int) -> None:
    if (
        not isinstance(marker_count, int)
        or isinstance(marker_count, bool)
        or marker_count not in SUPPORTED_MARKER_COUNTS
    ):
        raise ValueError(
            'marker_count must be one of 9, 10, 11, 12 or 20',
        )


def _default_marker_size(
    usable_area: CoordinateBounds,
    marker_count: int,
) -> int:
    columns, rows, _ = _layout_for_marker_count(marker_count)
    area_width = usable_area.right - usable_area.left
    area_height = usable_area.bottom - usable_area.top
    desired_size = round(min(area_width, area_height) * _DEFAULT_MARKER_SIZE_FRACTION)
    cell_size = min(area_width / columns, area_height / rows)
    maximum_size = math.floor(math.nextafter(cell_size, -math.inf))
    return min(desired_size, maximum_size)


def _coerce_marker_size(
    marker_size: object,
    usable_area: CoordinateBounds,
    marker_count: int,
) -> float:
    try:
        checked_marker_size = _coerce_finite_float(marker_size, 'marker_size')
    except ValueError:
        raise ValueError('marker_size must be a finite, positive number') from None
    if checked_marker_size <= 0:
        raise ValueError('marker_size must be a finite, positive number')
    columns, rows, _ = _layout_for_marker_count(marker_count)
    cell_width = (usable_area.right - usable_area.left) / columns
    cell_height = (usable_area.bottom - usable_area.top) / rows
    if checked_marker_size >= min(cell_width, cell_height):
        raise ValueError('marker_size must fit inside each pattern cell')
    return checked_marker_size


def _layout_for_marker_count(marker_count: int) -> tuple[int, int, frozenset[tuple[int, int]]]:
    layouts = {
        9: (3, 3, frozenset()),
        10: (5, 2, frozenset()),
        11: (4, 3, frozenset({(1, 1)})),
        12: (4, 3, frozenset()),
        20: (5, 4, frozenset()),
    }
    return layouts[marker_count]


def _build_raster_safe_axis_starts(
    area_start: float,
    area_end: float,
    axis_count: int,
    marker_size: float,
) -> tuple[float, ...]:
    rendered_marker_size = max(1, round(marker_size))
    first_render_start = math.ceil(area_start)
    first_start = max(
        area_start,
        _minimum_raster_safe_start(first_render_start),
    )
    last_render_start = math.floor(area_end) - rendered_marker_size
    last_raster_start = _maximum_raster_safe_start(last_render_start)
    last_geometry_start = math.nextafter(
        area_end - marker_size,
        -math.inf,
    )
    last_start = min(last_raster_start, last_geometry_start)
    if last_start < first_start:
        raise ValueError('marker_size must fit inside the raster-safe usable area')
    step = (last_start - first_start) / (axis_count - 1)
    return tuple(
        min(first_start + marker_idx * step, last_start)
        for marker_idx in range(axis_count)
    )


def _minimum_raster_safe_start(rendered_start: int) -> float:
    candidate = rendered_start - 0.5
    if round(candidate) >= rendered_start:
        return candidate
    return math.nextafter(candidate, math.inf)


def _maximum_raster_safe_start(rendered_start: int) -> float:
    candidate = rendered_start + 0.5
    if round(candidate) <= rendered_start:
        return candidate
    return math.nextafter(candidate, -math.inf)


def _build_marker_corners(
    usable_area: CoordinateBounds,
    x_start: float,
    y_start: float,
    marker_size: float,
) -> tuple[Point2D, ...]:
    x_end = min(
        x_start + marker_size,
        math.nextafter(usable_area.right, -math.inf),
    )
    y_end = min(
        y_start + marker_size,
        math.nextafter(usable_area.bottom, -math.inf),
    )
    return (
        Point2D(x_start, y_start),
        Point2D(x_end, y_start),
        Point2D(x_end, y_end),
        Point2D(x_start, y_end),
    )


def _coerce_finite_float(value: object, field_name: str) -> float:
    if not isinstance(value, Real) or isinstance(value, bool):
        raise ValueError(f'{field_name} must be a finite number')
    try:
        checked_value = float(value)
    except (OverflowError, TypeError, ValueError):
        raise ValueError(f'{field_name} must be a finite number') from None
    if not math.isfinite(checked_value):
        raise ValueError(f'{field_name} must be a finite number')
    return checked_value


__all__ = [
    'APRILTAG_36H11',
    'APRILTAG_FAMILIES',
